// ---- 钟面提亮：浅色表盘 + 深色指针，读作钟而不是黑盘 ----
mf.group('tower',()=>{
  const cx=-38,cy=36;
  mf.paint([cx-7,cy-7,15],[15,15,1],{style:SN});      // 表盘
  mf.paint([cx-6,cy-6,15],[13,13,1],{style:ST});      // 内圈留白
  mf.paint([cx-5,cy-5,15],[11,11,1],{style:SN});
  mf.paint([cx,cy+1,16],[1,5,1],{style:RU});          // 时针
  mf.paint([cx+1,cy,16],[4,1,1],{style:RU});          // 分针
  mf.paint([cx,cy,16],[1,1,1],{style:GD});
});

// ---- 窗户放大为带铜框的拱窗，玻璃 + 少量暖灯 ----
mf.group('building',()=>{
  for(const wx of [-28,-22,2,7]){
    mf.paint([wx-2,26,12],[8,15,1],{style:ST});        // 清出墙面
    mf.paint([wx,28,12],[4,8,1],{style:GL});
    mf.paint([wx+1,30,12],[1,3,1],{style:LA});
    B(wx-1,27,13,6,1,1,CU);                           // 窗台
    B(wx-1,28,13,1,9,1,CU); B(wx+4,28,13,1,9,1,CU);    // 竖框
    B(wx,37,13,4,1,1,CU); B(wx+1,38,13,2,1,1,CU);      // 拱顶
    B(wx+1,39,13,2,1,1,GD);
  }
  // 侧墙拱窗
  for(const wz of [-14,-8,2,8]){
    mf.paint([10,26,wz-1],[1,15,6],{style:ST});
    mf.paint([10,28,wz],[1,8,4],{style:GL});
    mf.paint([10,30,wz+1],[1,3,1],{style:LA});
    B(11,27,wz-1,1,1,6,CU); B(11,28,wz-1,1,9,1,CU); B(11,28,wz+4,1,9,1,CU);
  }
  // 腰线与扶壁，打破平墙
  B(-32,25,-22,45,1,37,SA);
  B(-33,13,13,1,30,2,ST); B(10,13,13,1,30,2,ST);
  B(-33,40,13,2,1,3,CU); B(-33,44,13,2,1,3,CU);
});

