{"baseRevision": 3, "seed": 7, "mode": "apply", "code": "mf.group('sign',()=>{
  // copper outer frame plaque on front wall face (z=13), above door
  mf.box([-18,31,13],[20,12,1],{style:'copper'});
  // dark inner panel for contrast
  mf.box([-17,32,13],[18,10,1],{style:'rubber'});
  // small gold rivets at frame corners
  mf.box([-18,31,13],[1,1,1],{style:'gold'});
  mf.box([1,31,13],[1,1,1],{style:'gold'});
  mf.box([-18,42,13],[1,1,1],{style:'gold'});
  mf.box([1,42,13],[1,1,1],{style:'gold'});
});
mf.group('lantern',()=>{
  const xs=[-20,0];
  for(const x of xs){
    // wall bracket arm reaching out in +z
    mf.box([x,24,13],[1,1,5],{style:'copper'});
    mf.box([x,23,17],[1,1,1],{style:'copper'});
    // chain
    mf.box([x,22,17],[1,2,1],{style:'copper'});
    // cap
    mf.box([x-1,20,16],[3,1,3],{style:'copper'});
    // glowing glass body with copper corner posts
    mf.box([x-1,18,16],[3,2,3],{style:'lamp'});
    for(const cx of [x-1,x+1]) for(const cz of [16,18]) mf.box([cx,18,cz],[1,2,1],{style:'copper'});
    // base
    mf.box([x-1,17,16],[3,1,3],{style:'copper'});
    mf.box([x,16,17],[1,1,1],{style:'gold'});
  }
});"}

